tokens.css:
--color-bg: #1a1708;
--color-surface: #26220f;
--color-text: #f7f3e6;
--color-text-muted: #a89f85;
--color-border: #3a3420;
--color-primary: #f0c419;
--color-on-primary: #1a1708;
--color-accent: #e0703a;
--color-on-accent: #1a1708;
--font-display: "Bodoni Moda", Georgia, serif;
--font-body: "Hanken Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 4px;
--radius-card: 8px;
--space-section: 112px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
